effect.shader:
void main(){
vec2 uv=acScreenNorm, px=1.0/max(acScreenSize,vec2(1.0));
vec4 base=texture2DCv(inputImg.texture,uv); vec3 sum=base.rgb; float w=1.0;
for(int y=-2;y<=2;y++) for(int x=-2;x<=2;x++){
if(x==0 && y==0) continue;
vec2 off=vec2(float(x),float(y))*px*radius*0.5;
vec3 s=texture2DCv(inputImg.texture,clamp(uv+off,0.0,1.0)).rgb;
float edge=1.0-smoothstep(sensitivity,sensitivity*2.0,length(s-base.rgb));
float weight=edge/(1.0+dot(vec2(float(x),float(y)),vec2(float(x),float(y)))); sum+=s*weight; w+=weight;
}
vec3 blurred=sum/max(w,0.0001); float mask=smoothstep(split-feather,split+feather,uv.x);
vec3 outCol=mix(base.rgb,blurred,strength*mask);
gl_FragColor=vec4(outCol,base.a);
}
